// Build one Apify call per platform from the inputs above.
const s = $input.first().json;
const calls = [];
const max = Number(s.maxItemsPerPlatform) || 20;
calls.push({ platform: 'Taobao/Tmall', actor: 'tubetext~taobao-tmall-scraper',
  input: { keywords: [s.taobaoKeyword || s.keyword], maxItemsPerQuery: max } });
calls.push({ platform: 'AliExpress', actor: 'tubetext~aliexpress-search-scraper',
  input: { keywords: [s.keyword], maxItemsPerKeyword: max, sortBy: 'orders', shipTo: s.shipTo || 'US', currency: 'USD', skipNewShopperDeals: true } });
const tts = (s.tiktokShopUrls || []).map(u => String(u).trim()).filter(Boolean);
if (tts.length) calls.push({ platform: 'TikTok Shop', actor: 'tubetext~tiktok-shop-product-scraper',
  input: { urls: tts, maxProductsPerListing: max } });
return calls.map(c => ({ json: c }));

// Native currencies only: no FX conversion or cross-currency price ranking.
// Keep one row per platform; legacy USD fields summarize confirmed USD only.
const knownCurrencies = new Set(Intl.supportedValuesOf('currency'));
const platformOf = it => /taobao|tmall/i.test(it.url || '') ? 'Taobao/Tmall'
  : /aliexpress/i.test(it.url || '') ? 'AliExpress'
  : /tiktok/i.test(it.url || '') ? 'TikTok Shop' : null;
const amount = x => typeof x === 'number' && Number.isFinite(x) && x >= 0 ? x : null;
const quote = it => {
  if (Object.prototype.hasOwnProperty.call(it, 'priceCNY')) return {value: amount(it.priceCNY), currency: 'CNY'};
  const code = typeof it.currency === 'string' ? it.currency.trim().toUpperCase() : '';
  return {value: amount(it.price), currency: knownCurrencies.has(code) ? code : null};
};
const round = n => Number(n.toFixed(2));
const stats = items => {
  const prices = items.map(x => x.quote.value).filter(x => x !== null).sort((a,b) => a-b);
  const m = Math.floor(prices.length / 2);
  return {products: items.length, pricedProducts: prices.length,
    minPrice: prices.length ? round(prices[0]) : null,
    medianPrice: prices.length ? round(prices.length % 2 ? prices[m] : prices[m-1] / 2 + prices[m] / 2) : null};
};
const groups = new Map();
for (const {json: it} of $input.all()) {
  if (!it || it.status !== 'ok' || it.error || it.errorCode) continue;
  const platform = platformOf(it);
  if (!platform) continue;
  if (!groups.has(platform)) groups.set(platform, []);
  groups.get(platform).push({item: it, quote: quote(it)});
}
return [...groups].map(([platform, items]) => {
  const currencies = [...new Set(items.map(x => x.quote.currency).filter(Boolean))].sort();
  const priceGroups = currencies.map(currency => ({currency, ...stats(items.filter(x => x.quote.currency === currency))}));
  const usd = priceGroups.find(x => x.currency === 'USD');
  const sold = it => amount(it.soldCount) ?? 0;
  // Stable order for equal sales counts avoids ranking different currencies by face value.
  const top = [...items].sort((a,b) => sold(b.item)-sold(a.item)).slice(0,5);
  return {json: {platform, products: items.length,
    minPriceUSD: usd?.minPrice ?? null, medianPriceUSD: usd?.medianPrice ?? null,
    top5: top.map(({item: it, quote: q}) => {
      const price = q.value === null ? 'Price unavailable' : `${q.value.toFixed(2)} ${q.currency || '(currency unknown)'}`;
      return `${price} | ${sold(it) ? sold(it) + ' sold | ' : ''}${String(it.title || '').slice(0,60)} | ${it.url}`;
    }).join('\n'),
    priceGroups,
    missingPriceProducts: items.filter(x => x.quote.value === null).length,
    unknownCurrencyProducts: items.filter(x => x.quote.currency === null).length,
  }};
});
